  /* ---------- Login (redesigned: organic field/market identity) ---------- */
  .login-screen{
    min-height:100vh;display:flex;align-items:stretch;justify-content:center;
    position:relative;overflow:hidden;background:#F6F4EC;
  }
  .login-visual{
    flex:1 1 46%;position:relative;display:flex;flex-direction:column;justify-content:flex-end;
    /* Background diganti pakai foto produk Agrinesia asli (dipakai ulang dari asset yang
       sudah tertanam di ::before versi mobile -- base64 sama, jadi tidak nambah bobot file)
       + overlay gradasi hijau gelap DI ATASNYA supaya kontras teks (badge/judul/stats)
       tetap terjaga, alih-alih cuma gradient hijau polos seperti sebelumnya. */
    background-image:
      /* Gradasi overlay dipecah jadi banyak titik henti (bukan 3) supaya perpindahan warna
         hijau-nya halus dan tidak muncul "garis/banding" (color banding) di layar. */
      linear-gradient(180deg, rgba(255,255,255,.10) 0%, rgba(255,255,255,0) 38%, rgba(232,246,238,.55) 100%),
      url('data:image/jpeg;base64,');
    background-size:cover;background-position:50% 0%;
    padding:56px 52px;overflow:hidden;min-width:0;
  }
  .login-visual::before{
    /* FIX "garis-garis" di panel hijau: sebelumnya di sini ada pola garis diagonal tajam
       (repeating-linear-gradient, garis 2px tiap 36px) + mask -- itulah yang tampak sebagai
       garis-garis kasar di atas foto. Diganti dengan sorotan cahaya LEMBUT (radial-gradient
       banyak titik henti, tanpa tepi keras) supaya tetap ada kesan "hidup" tapi halus. */
    content:'';position:absolute;inset:0;pointer-events:none;
    background:
      radial-gradient(ellipse 70% 55% at 22% 24%,
        rgba(255,255,255,.075) 0%,
        rgba(255,255,255,.058) 22%,
        rgba(255,255,255,.038) 42%,
        rgba(255,255,255,.018) 62%,
        rgba(255,255,255,.006) 80%,
        rgba(255,255,255,0) 100%);
  }
  .login-visual::after{
    /* Lingkaran cahaya oranye: tepi dulu memotong tegas di 68% (kelihatan seperti lingkaran
       bergaris). Sekarang memudar bertahap sampai 0 di tepi. Tanpa border-radius/tepi keras,
       dan sedikit blur supaya semua transisi menyatu mulus dengan foto. */
    content:'';position:absolute;width:760px;height:760px;border-radius:50%;pointer-events:none;
    background:radial-gradient(circle,
      rgba(242,153,74,.20) 0%,
      rgba(242,153,74,.155) 16%,
      rgba(242,153,74,.11) 32%,
      rgba(242,153,74,.068) 48%,
      rgba(242,153,74,.034) 62%,
      rgba(242,153,74,.012) 76%,
      rgba(242,153,74,0) 90%);
    filter:blur(14px);
    top:-260px;right:-220px;
  }
  .login-visual-badge{
    position:relative;z-index:1;display:inline-flex;align-items:center;gap:8px;
    background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.18);
    padding:7px 14px 7px 10px;border-radius:999px;font-size:11.5px;font-weight:700;
    letter-spacing:.03em;color:#E9F6EE;width:fit-content;margin-bottom:auto;
    margin-top:4px;backdrop-filter:blur(6px);
  }
  .login-visual-badge svg{width:15px;height:15px;flex-shrink:0;}
  .login-visual-copy{position:relative;z-index:1;color:#fff;}
  .login-visual-title{
    font-family:'Fraunces','Georgia',serif;font-size:34px;line-height:1.18;font-weight:600;
    letter-spacing:-.01em;margin:0 0 14px;max-width:420px;
  }
  .login-visual-title em{font-style:normal;color:#8FE0B4;}
  .login-visual-desc{font-size:14px;line-height:1.65;color:rgba(255,255,255,.78);max-width:380px;margin:0 0 34px;}
  .login-visual-stats{position:relative;z-index:1;display:flex;gap:28px;padding-top:26px;border-top:1px solid rgba(255,255,255,.16);}
  .login-visual-stat-num{font-family:'Fraunces','Georgia',serif;font-size:24px;font-weight:600;color:#fff;line-height:1;}
  .login-visual-stat-label{font-size:11px;color:rgba(255,255,255,.62);margin-top:6px;letter-spacing:.02em;}

  .login-form-side{
    flex:1 1 54%;display:flex;align-items:center;justify-content:center;
    padding:32px;position:relative;min-width:0;
  }
  .login-card{
    background:#FFFFFF;padding:44px 44px;border-radius:22px;
    box-shadow:0 24px 60px rgba(11,61,46,.1), 0 2px 10px rgba(11,61,46,.06);
    width:100%;max-width:460px;position:relative;z-index:1;border:1px solid rgba(11,61,46,.05);
