  .login-logo{display:flex;flex-direction:column;align-items:flex-start;text-align:left;gap:0;margin-bottom:30px;}
  .logo-mark{width:42px;height:42px;border-radius:12px;background:var(--ag-surface);box-shadow:0 1px 2px rgba(6,30,22,.06);color:#fff;display:flex;align-items:center;justify-content:center;font-weight:800;overflow:hidden;flex-shrink:0;}
  .logo-mark .brand-mark-img{width:100%;height:100%;object-fit:contain;padding:6px;box-sizing:border-box;display:block;}
  .logo-mark.small{width:40px;height:40px;border-radius:11px;flex-shrink:0;}
  .login-logo .logo-mark{width:64px;height:64px;border-radius:17px;box-shadow:0 4px 10px rgba(6,30,22,.12);margin-bottom:18px;}
  .login-logo .logo-mark .brand-mark-img{padding:11px;}
  .login-logo-appname{font-size:12.5px;font-weight:800;letter-spacing:.05em;text-transform:uppercase;color:var(--ag-green);margin:-8px 0 4px;}
  .logo-mark.has-logo-img{background:var(--ag-surface);border:1px solid var(--ag-gray-200);}
  .logo-mark.has-logo-img img{width:100%;height:100%;object-fit:contain;padding:3px;box-sizing:border-box;}
  .logo-title{font-weight:800;font-size:15px;color:var(--ag-dark-green);line-height:1.1;}
  .logo-sub{font-size:10px;color:var(--ag-orange);letter-spacing:.06em;}
  .login-logo .logo-title{display:none;}
  .login-logo .logo-sub{display:none;}
  .login-heading{margin:0 0 8px;font-size:26px;font-weight:700;color:var(--ag-gray-900);font-family:'Fraunces','Georgia',serif;letter-spacing:-.01em;white-space:nowrap;}
  .login-subheading{margin:0 0 28px;color:var(--ag-gray-500);font-size:14.5px;line-height:1.55;}

  .input-with-icon{position:relative;}
  .input-with-icon .field-icon{
    position:absolute;left:12px;top:50%;transform:translateY(-50%);width:16px;height:16px;
    color:var(--ag-gray-400);pointer-events:none;z-index:1;
  }
  .input-with-icon input{padding-left:36px !important;}
  /* Dashboard Settings (Banner/Kategori/Produk Unggulan) popup: field-icon juga dipakai
     di depan <select> ("Pilih Produk", "Aksi saat diklik") & <svg> polos tanpa class (dari
     dcInputWithIcon_), bukan cuma di <input> seperti popup Ganti Password. */
  .input-with-icon > svg{
    position:absolute;left:12px;top:50%;transform:translateY(-50%);width:16px;height:16px;
    color:var(--ag-gray-400);pointer-events:none;z-index:1;
  }
  .input-with-icon select{padding-left:36px !important;}
  .input-with-icon input[type="password"],
  .input-with-icon input[data-pw-visible]{padding-right:38px !important;}
  .pw-toggle-btn{
    position:absolute;right:6px;top:50%;transform:translateY(-50%);width:28px;height:28px;
    border:none;background:none;color:var(--ag-gray-400);cursor:pointer;display:flex;
    align-items:center;justify-content:center;border-radius:7px;transition:background .15s,color .15s;z-index:2;
  }
  .pw-toggle-btn:hover{background:var(--ag-gray-100);color:var(--ag-gray-600);}
  .pw-toggle-btn svg{width:17px;height:17px;}
  .pw-toggle-btn .eye-off{display:none;}
  .pw-toggle-btn.is-visible .eye-on{display:none;}
  .pw-toggle-btn.is-visible .eye-off{display:block;}

  .login-row-between{display:flex;align-items:center;justify-content:space-between;margin:-6px 0 22px;}
  .remember-check{display:flex;align-items:center;gap:7px;font-size:12.5px;color:var(--ag-gray-600);cursor:pointer;user-select:none;}
  .remember-check input{
    width:15px;height:15px;cursor:pointer;margin:0;-webkit-appearance:none;appearance:none;
    background:#fff;border:1.5px solid var(--ag-gray-300);border-radius:4px;position:relative;flex-shrink:0;
    transition:background .15s,border-color .15s;
  }
  .remember-check input:checked{background:var(--ag-green);border-color:var(--ag-green);}
  .remember-check input:checked::after{
    /* Centang di-center pakai transform (bukan left/top manual) supaya presisi di
       tengah kotak checkbox persis berapa pun ukuran border-nya — sebelumnya posisi
       left/top fixed sedikit geser dari tengah sehingga kelihatan "kurang di tengah". */
    content:'';position:absolute;left:50%;top:46%;width:4px;height:8px;
    border:solid #fff;border-width:0 2px 2px 0;
    transform:translate(-50%,-50%) rotate(45deg);
