  .agent-wrap-tbl .ag-person-sub{display:flex;align-items:center;gap:4px;flex-wrap:wrap;}
  .agent-wrap-tbl .cell-agent-name{white-space:normal !important;overflow:visible !important;text-overflow:clip !important;font-weight:600;color:var(--ag-gray-800,#1f2d27);}
  .agent-wrap-tbl .cell-agent-sub{white-space:normal !important;overflow:visible !important;text-overflow:clip !important;font-size:10.5px;color:var(--ag-gray-500);margin-top:2px;}
