  .agent-wrap-tbl .row-actions{gap:4px !important;}
  .agent-wrap-tbl .row-actions .action-btn{width:28px !important;height:28px !important;}
  .agent-wrap-tbl .row-actions .action-btn svg{width:14px !important;height:14px !important;}
  .agent-wrap-tbl .id-chip{font-size:10px;padding:1px 6px;}

  /* ===== Dashboard Settings: tertata & modern ===== */
  .dset-intro{display:flex;gap:12px;align-items:flex-start;padding:14px 16px;margin-bottom:16px;border-radius:16px;background:linear-gradient(120deg,#e8f8f0,#f4fbf8);border:1px solid #c8ebd9;color:#0b5d44;}
  .dset-intro-ico{flex:0 0 34px;height:34px;border-radius:11px;background:linear-gradient(135deg,#16a36b,#0e7a52);color:#fff;display:flex;align-items:center;justify-content:center;}
  .dset-intro-ico svg{width:17px;height:17px;}
  .dset-intro b{display:block;font-size:13.5px;margin-bottom:2px;}
  .dset-intro span:not(.dset-intro-ico){display:block;font-size:12px;line-height:1.5;color:#2f6f58;}
  .dset-grid{display:grid;grid-template-columns:1fr;gap:16px;align-items:start;}
  @media(min-width:1280px){.dset-grid{grid-template-columns:1fr 1fr;}.dset-grid .dset-banner{grid-column:1 / -1;}}
  .dset-card{padding:0 !important;margin:0 !important;overflow:hidden;}
  .dset-head{display:flex;align-items:center;gap:12px;padding:14px 16px;border-bottom:1px solid var(--ag-gray-200);background:linear-gradient(180deg,#fafdfb,#fff);}
  .dset-head-ico{flex:0 0 36px;height:36px;border-radius:11px;display:flex;align-items:center;justify-content:center;background:#e4f7ee;color:#0e7a52;}
  .dset-head-ico svg{width:18px;height:18px;}
  .dset-banner .dset-head-ico{background:#e5eeff;color:#1d4ed8;} .dset-trending .dset-head-ico{background:#fff1dc;color:#b45309;} .dset-product .dset-head-ico{background:#efe9ff;color:#6d28d9;}
  .dset-head-txt{flex:1;min-width:0;}
  .dset-head-title{font-size:14px;font-weight:700;color:var(--ag-gray-900,#0f1f18);}
  .dset-head-desc{font-size:11.5px;color:var(--ag-gray-500);margin-top:1px;}
  .dset-count{font-size:11px;font-weight:600;color:var(--ag-gray-600);background:var(--ag-gray-100);border-radius:999px;padding:4px 10px;white-space:nowrap;}
  .dset-count b{color:#0e7a52;}
  .dset-card .dash-config-list{display:flex;flex-direction:column;gap:8px;padding:12px 14px 14px;}
  .dset-card .empty-state{padding:26px 16px;font-size:12.5px;}
  .dset-row{display:flex !important;align-items:center;gap:12px;padding:10px 12px !important;border:1px solid var(--ag-gray-200) !important;border-radius:14px !important;background:var(--ag-surface) !important;transition:border-color .15s,box-shadow .15s,opacity .15s;}
  .dset-row:hover{border-color:#bfe5d2 !important;box-shadow:0 6px 16px -8px rgba(14,122,82,.35);}
  .dset-row.is-off{opacity:.62;background:var(--ag-gray-50) !important;}
  .dset-num{flex:0 0 22px;height:22px;border-radius:7px;background:var(--ag-gray-100);color:var(--ag-gray-600);font-size:11px;font-weight:700;display:flex;align-items:center;justify-content:center;}
  .dset-thumb{width:46px;height:46px;object-fit:cover;border-radius:10px;flex:0 0 auto;border:1px solid var(--ag-gray-200);}
  .dset-thumb-wide{width:96px;height:46px;}
  .dset-thumb-empty{background:var(--ag-gray-100);}
  .dset-row .dash-config-row-info{flex:1;min-width:0;}
  .dset-row .dash-config-row-title{font-size:13px;font-weight:700;color:var(--ag-gray-900,#0f1f18);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
  .dset-row .dash-config-row-sub{font-size:11.5px;color:var(--ag-gray-500);margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
  .dset-status{flex:0 0 auto;}
  .dset-row .dash-config-row-controls{display:flex;align-items:center;gap:10px;flex:0 0 auto;}
  .dset-row .dash-config-row-order{display:flex;align-items:center;gap:6px;font-size:11px;color:var(--ag-gray-500);font-weight:600;}
  .dset-row .dash-sort-input{width:52px !important;height:30px;text-align:center;border-radius:9px;border:1px solid var(--ag-gray-200);background:var(--ag-surface);font-weight:700;}
  .dset-row .dash-sort-input:focus{outline:none;border-color:#16a36b;box-shadow:0 0 0 3px rgba(22,163,107,.18);}
  .dset-row .switch{display:inline-block !important;}
  @media(max-width:760px){.dset-row{flex-wrap:wrap;}.dset-row .dash-config-row-controls{width:100%;justify-content:flex-end;}.dset-head{flex-wrap:wrap;}}
  html[data-theme="dark"] .dset-intro{background:rgba(16,185,129,.1);border-color:rgba(16,185,129,.3);color:#a7f3d0;}
  html[data-theme="dark"] .dset-intro span:not(.dset-intro-ico){color:#86e0bd;}
  html[data-theme="dark"] .dset-head{background:rgba(255,255,255,.03);}
  html[data-theme="dark"] .dset-head-title,html[data-theme="dark"] .dset-row .dash-config-row-title{color:#e8f1ec;}
  /* Tabel Agent: Email/Telepon satu baris; Tombol Tambah bertema terang */
  .agent-wrap-tbl .cell-1l{display:block;max-width:210px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap !important;font-size:12px;color:var(--ag-gray-700,#33443c);}
  .agent-wrap-tbl .data-table td{white-space:nowrap !important;}
  .agent-wrap-tbl .data-table td:first-child{white-space:normal !important;min-width:190px;}
  .agent-wrap-tbl .cell-area{display:inline-block;max-width:130px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;vertical-align:middle;}
  .agent-wrap-tbl .cell-muted{color:var(--ag-gray-400,#9aa8a1);}
  html .btn.btn-primary.btn-add{background:var(--ag-green-soft) !important;color:#166a42 !important;border:1px solid rgba(30,122,76,.38) !important;box-shadow:none !important;font-weight:700;filter:none !important;}
  html .btn.btn-primary.btn-add:hover{background:var(--ag-green-soft-hover) !important;border-color:var(--ag-green) !important;box-shadow:0 3px 10px rgba(30,122,76,.16) !important;transform:translateY(-1px);filter:none !important;}
  html .btn.btn-primary.btn-add svg{color:var(--ag-green);}
  html[data-theme="dark"] .btn.btn-primary.btn-add{color:#6ee7b7 !important;border-color:rgba(110,231,183,.35) !important;}
  /* ===== REDESIGN: Dashboard Agent & Popup Buat PO (modern, e-commerce) ===== */
  .agent-dash{--pk-r:18px;--pk-bd:var(--ag-gray-200);--pk-sh:0 1px 2px rgba(16,40,30,.05),0 4px 14px rgba(16,40,30,.05);}
  .agent-dash-greeting{font-size:18px;font-weight:500;color:var(--ag-gray-600);padding:2px 2px 0;}
  .agent-dash-greeting strong{color:var(--ag-gray-900);font-weight:800;}
  .agent-banner-card{border-radius:20px;box-shadow:var(--pk-sh);}
  .agent-shortcut-grid{grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;}
  .agent-shortcut-item{display:grid !important;grid-template-columns:40px minmax(0,1fr);grid-template-rows:auto auto;column-gap:10px;row-gap:1px;align-items:center !important;justify-items:start;padding:12px 14px !important;border-radius:var(--pk-r) !important;border:1px solid var(--pk-bd) !important;background:var(--ag-surface) !important;box-shadow:var(--pk-sh) !important;}
  .agent-shortcut-icon{grid-row:1 / span 2;width:40px !important;height:40px !important;border-radius:12px !important;}
  .agent-shortcut-icon svg{width:20px !important;height:20px !important;}
  .agent-shortcut-label{font-size:13px !important;font-weight:700 !important;text-align:left !important;align-self:end;white-space:normal;overflow-wrap:anywhere;}
  .agent-shortcut-sublabel{font-size:11px !important;text-align:left !important;margin-top:0 !important;align-self:start;white-space:normal;overflow-wrap:anywhere;}
  .agent-shortcut-item .agent-shortcut-label:only-of-type{grid-row:1 / span 2;align-self:center;}
  .agent-section-head{font-size:17px !important;font-weight:800 !important;letter-spacing:-.01em;margin-top:10px !important;}
  .agent-section-subtitle{font-size:12px !important;color:var(--ag-gray-500) !important;}
  .agent-category-row{gap:12px !important;padding:2px 2px 6px !important;}
  .agent-category-item{width:86px !important;gap:8px !important;padding:10px 4px 8px;border:1px solid var(--pk-bd);border-radius:var(--pk-r);background:var(--ag-surface);box-shadow:var(--pk-sh);}
  .agent-category-thumb{width:54px !important;height:54px !important;border:1px solid var(--pk-bd);}
  .agent-category-label{font-size:11px !important;line-height:1.25 !important;white-space:normal !important;overflow:visible !important;text-overflow:clip !important;display:block !important;overflow-wrap:anywhere;max-width:100%;}
  .agent-trend-card,.agent-product-card{border:1px solid var(--pk-bd) !important;border-radius:var(--pk-r) !important;background:var(--ag-surface) !important;box-shadow:var(--pk-sh) !important;padding:8px 8px 12px !important;display:flex;flex-direction:column;transition:box-shadow .2s,transform .2s;}
  .agent-trend-card{flex:0 0 200px !important;width:200px;}
  .agent-trend-img,.agent-product-img{border-radius:12px !important;aspect-ratio:1/1 !important;width:100%;height:auto !important;overflow:hidden;margin-bottom:10px !important;background:var(--ag-gray-100);}
  .agent-trend-img img,.agent-product-img img{width:100%;height:100%;object-fit:cover;}
  .agent-product-badge{top:14px !important;left:14px !important;background:rgba(255,255,255,.94) !important;color:var(--ag-green) !important;border:1px solid rgba(30,122,76,.25);font-size:10px !important;font-weight:800;letter-spacing:.03em;padding:3px 9px !important;border-radius:999px !important;max-width:calc(100% - 28px);box-shadow:0 1px 4px rgba(0,0,0,.08);z-index:2;}
  .agent-product-name{font-size:13px !important;font-weight:700 !important;line-height:1.3 !important;min-height:0 !important;padding:0 4px;overflow-wrap:anywhere;word-break:normal;color:var(--ag-gray-900);flex:1;}
  .agent-product-price-row{padding:0 4px;margin-top:8px;gap:8px;flex-wrap:wrap;}
  .agent-product-price{font-size:14px !important;font-weight:800 !important;color:var(--ag-gray-900) !important;}
  .agent-product-add-btn{width:34px !important;height:34px !important;font-size:20px !important;line-height:1;background:var(--ag-green-soft) !important;color:var(--ag-green) !important;border:1px solid rgba(30,122,76,.3) !important;border-radius:50%;}
  .agent-product-add-btn:hover{background:var(--ag-green) !important;color:#fff !important;}
  .agent-product-qty-stepper{background:var(--ag-green-soft) !important;border-radius:999px !important;padding:3px !important;}
  .agent-product-qty-stepper button{width:26px !important;height:26px !important;}
  .agent-product-grid{grid-template-columns:repeat(auto-fill,minmax(200px,1fr)) !important;gap:14px !important;}
  @media(max-width:700px){
    .agent-shortcut-grid{grid-template-columns:repeat(2,minmax(0,1fr)) !important;gap:10px;}
    .agent-product-grid{grid-template-columns:repeat(2,minmax(0,1fr)) !important;gap:10px !important;}
    .agent-trend-card{flex-basis:170px !important;width:170px;}
    .agent-dash-greeting{font-size:16px;}
  }

  /* Popup Buat PO: dua panel (katalog | keranjang) */
  .modal-box:has(.po-shell){max-width:1080px !important;width:min(1080px,96vw) !important;}
  .po-shell{display:grid;grid-template-columns:minmax(0,1fr) 380px;gap:22px;align-items:start;}
  .po-main,.po-side{min-width:0;}
  .po-side{background:var(--ag-surface);border:1px solid var(--ag-gray-200);border-radius:18px;padding:16px;box-shadow:0 1px 2px rgba(16,40,30,.05),0 8px 22px rgba(16,40,30,.06);}
  .po-side .po-cart-section{border:0 !important;padding:0 !important;box-shadow:none !important;background:none !important;margin:0 0 12px;}
  .po-side .po-cart-title{font-size:14px;font-weight:800;margin-bottom:6px;}
  .po-side #poCartList{max-height:260px;overflow-y:auto;}
  .po-side .field-row-2{grid-template-columns:1fr !important;gap:0;}
  .po-side .form-group{margin-bottom:10px;}
  .po-side .form-group label{font-size:12px;font-weight:700;}
  .po-search-wrap{margin-bottom:12px !important;}
  .po-product-search{border-radius:14px !important;height:44px;background:var(--ag-gray-100) !important;border-color:transparent !important;}
  .po-product-search:focus{background:var(--ag-surface) !important;}
  .po-category-tabs{padding:0 0 12px !important;}
  .po-category-tab{border-radius:999px !important;padding:7px 14px !important;font-size:12px !important;font-weight:700 !important;}
  .po-category-tab.is-active{background:var(--ag-green-soft) !important;color:var(--ag-green) !important;border-color:rgba(30,122,76,.45) !important;}
  .po-product-grid{grid-template-columns:repeat(auto-fill,minmax(150px,1fr)) !important;gap:12px !important;max-height:min(58vh,560px) !important;padding:2px 4px 4px 2px !important;margin-bottom:0 !important;}
  .po-product-tile{display:flex;flex-direction:column;border-radius:16px !important;border:1px solid var(--ag-gray-200) !important;background:var(--ag-surface);box-shadow:0 1px 2px rgba(16,40,30,.04);overflow:hidden;cursor:pointer;}
  .po-product-tile.in-cart{border-color:var(--ag-green) !important;box-shadow:0 0 0 2px var(--ag-green-soft) !important;}
  .po-product-thumb{position:relative;aspect-ratio:1/1;}
  .po-tile-cat{position:absolute;top:8px;left:8px;background:rgba(255,255,255,.94);color:var(--ag-gray-700);font-size:10px;font-weight:800;padding:2px 8px;border-radius:999px;box-shadow:0 1px 3px rgba(0,0,0,.1);}
  .po-product-info{display:flex;flex-direction:column;flex:1;padding:10px 10px 10px !important;gap:4px;}
  .po-product-name{font-size:12.5px !important;line-height:1.3 !important;white-space:normal !important;overflow:visible !important;display:block !important;-webkit-line-clamp:unset !important;overflow-wrap:anywhere;flex:1;}
  .po-product-price{font-size:13px !important;font-weight:800 !important;color:var(--ag-gray-900) !important;margin-top:2px !important;}
  .po-product-price small{font-size:10.5px;font-weight:600;color:var(--ag-gray-500);}
  .po-tile-add{margin-top:6px;border:1px solid rgba(30,122,76,.4);background:var(--ag-green-soft);color:var(--ag-green);font-weight:800;font-size:12px;border-radius:10px;padding:8px 0;cursor:pointer;width:100%;}
  .po-tile-add:hover{background:var(--ag-green);color:#fff;}
  .po-tile-stepper{margin-top:6px;display:flex;align-items:center;justify-content:space-between;background:var(--ag-green-soft);border-radius:10px;padding:3px;}
  .po-tile-stepper button{width:30px;height:30px;border:0;border-radius:8px;background:var(--ag-green);color:#fff;font-size:17px;font-weight:700;cursor:pointer;line-height:1;}
  .po-tile-stepper span{font-weight:800;font-size:14px;color:var(--ag-green);min-width:24px;text-align:center;}
  .po-estimate-box{background:var(--ag-gray-100) !important;border:1px solid var(--ag-gray-200) !important;border-radius:14px !important;padding:12px 14px !important;margin-top:6px;}
  .po-sum-row{display:flex;justify-content:space-between;gap:10px;font-size:12.5px;color:var(--ag-gray-600);padding:3px 0;}
  .po-sum-row b{color:var(--ag-gray-900);font-weight:700;text-align:right;}
  .po-sum-total{border-top:1px dashed var(--ag-gray-300);margin-top:6px;padding-top:9px;font-size:13px;font-weight:800;color:var(--ag-gray-900);align-items:baseline;}
  .po-sum-total strong{font-size:18px !important;color:var(--ag-green) !important;}
  .po-cart-row{border-radius:12px;}
  @media(max-width:860px){
    .modal-box:has(.po-shell){width:100% !important;}
    .po-shell{grid-template-columns:minmax(0,1fr);gap:14px;}
    .po-product-grid{grid-template-columns:repeat(2,minmax(0,1fr)) !important;max-height:50vh !important;}
    .po-side #poCartList{max-height:none;}
  }
  /* FIX: ringkasan estimasi tidak boleh melebihi panel (override display:flex lama) */
  .po-side,.po-side *{box-sizing:border-box;}
  .po-side{overflow:hidden;max-width:100%;}
  .po-side .po-estimate-box{display:block !important;width:100%;max-width:100%;overflow:hidden;}
  .po-side .po-sum-row{display:flex;align-items:baseline;justify-content:space-between;gap:12px;width:100%;}
  .po-side .po-sum-row span{flex:0 0 auto;}
  .po-side .po-sum-row b,.po-side .po-sum-row strong{min-width:0;text-align:right;overflow-wrap:anywhere;}
  .po-side .po-sum-total{flex-wrap:nowrap;border-top:1px dashed var(--ag-gray-300);}
  .po-side .po-sum-total strong{font-size:17px !important;white-space:nowrap;}
  .po-side .form-group input,.po-side .form-group select,.po-side .form-group textarea,.po-side .date-field-wrap{width:100%;max-width:100%;}
  @media(max-width:860px){.po-side{padding:14px;}.po-side .po-sum-total strong{font-size:16px !important;}}
  /* ===== FIX: search tidak tumpang tindih ===== */
  .po-search-wrap .po-product-search{padding-left:42px !important;}
  .po-search-wrap svg{left:14px !important;width:17px !important;height:17px !important;z-index:2;}
  .filter-search input{padding-left:38px !important;}
  .filter-search-icon{left:13px !important;}

  /* ===== FILTER: kiri-kanan (grid), bisa hide/unhide ===== */
  .filter-top,.filter-fields,.filter-foot{display:contents;}
  .filter-toggle{display:none;}
  @media(max-width:900px){
    .filter-bar--c{display:flex !important;flex-direction:column;align-items:stretch;gap:10px;padding:12px !important;flex-wrap:nowrap !important;}
    .filter-bar--c .filter-top{display:flex;gap:8px;align-items:center;width:100%;}
    .filter-bar--c .filter-search{flex:1 1 auto !important;min-width:0 !important;max-width:none !important;}
    .filter-toggle{display:flex;position:relative;align-items:center;justify-content:center;flex:0 0 40px;width:40px;height:40px;border-radius:12px;border:0;background:var(--ag-green);color:#fff;cursor:pointer;box-shadow:0 4px 10px rgba(30,122,76,.28);}
    .filter-toggle svg{width:19px;height:19px;}
    .filter-toggle-badge{position:absolute;top:-6px;right:-6px;min-width:18px;height:18px;padding:0 4px;border-radius:9px;background:#f59e0b;color:#fff;font-size:10px;font-weight:800;display:flex;align-items:center;justify-content:center;border:2px solid var(--ag-surface);}
    .filter-bar--c .filter-controls-row{display:none !important;flex-direction:column;gap:10px;width:100% !important;flex:none !important;}
    .filter-bar--c.is-open .filter-controls-row{display:flex !important;}
    .filter-bar--c .filter-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;width:100%;}
    .filter-bar--c .filter-fields > :nth-child(odd):last-child{grid-column:1 / -1;}
    .filter-bar--c .filter-select-wrap{max-width:none !important;width:100%;min-width:0;}
    .filter-bar--c .filter-select{width:100% !important;font-size:12.5px !important;text-overflow:ellipsis;}
    .filter-bar--c .filter-daterange{grid-column:1 / -1;display:grid !important;grid-template-columns:minmax(0,1fr) 14px minmax(0,1fr);align-items:center;gap:6px;width:100%;flex:none !important;}
    .filter-bar--c .filter-daterange .date-field-wrap{width:100%;min-width:0;}
    .filter-bar--c .filter-foot{display:flex;align-items:center;justify-content:space-between;gap:8px;width:100%;}
    .filter-bar--c .filter-reset-btn{flex:0 0 auto;padding:0 14px;}
    .filter-bar--c .filter-count-pill{margin-left:auto;}
    /* Laporan (filter-bar tanpa panel): tanggal 2 kolom kiri-kanan */
    .filter-bar:not(.filter-bar--c) .filter-daterange{display:grid !important;grid-template-columns:minmax(0,1fr) 14px minmax(0,1fr);width:100%;gap:6px;}
    .filter-bar:not(.filter-bar--c) .filter-controls-row{display:flex;flex-wrap:wrap;gap:8px;width:100% !important;}
  }

  /* ===== FIX: teks menu "Lainnya" tidak terlihat ===== */
  #bottomMoreSheetNav .nav-item,#bottomMoreSheetNav .nav-item .nav-label,#bottomMoreSheetNav .nav-item .nav-icon{color:var(--ag-gray-800,#1f2d27) !important;opacity:1 !important;}
  #bottomMoreSheetNav .nav-item .nav-icon svg{stroke:currentColor !important;opacity:1 !important;}
