  .eb-kpi-compact .kpi-value{font-size:17px !important;overflow-wrap:anywhere;}
  .eb-kpi-compact .kpi-label{font-size:9.5px !important;line-height:1.25;margin:3px 0 0 !important;}
  @media (min-width:861px){.eb-kpi-compact{grid-template-columns:repeat(4,minmax(0,1fr)) !important;}}
  .eb-dash .eb-chart-wrap{height:170px;}
  .eb-dash .card{padding:14px !important;border-radius:18px;}
  .eb-dash .section-title{font-size:14px;}

  /* 3) QR Code */
  .eb-qr-page{gap:14px;padding:4px 0 20px;}
  .eb-qr-card{padding:0 !important;overflow:hidden;max-width:360px !important;gap:0 !important;border-radius:24px !important;}
  .eb-qr-top{width:100%;box-sizing:border-box;display:flex;align-items:center;justify-content:space-between;gap:8px;padding:12px 16px;
    background:linear-gradient(135deg,#1E7A4C 0%,#0B3D2E 100%);color:#fff;}
  .eb-qr-brandwrap{display:flex;align-items:center;gap:8px;min-width:0;}
  .eb-qr-top .eb-qr-logo{width:26px;height:26px;border-radius:8px;background:rgba(255,255,255,.18);color:#fff;align-items:center;justify-content:center;flex:none;}
