  .eb-qr-top .eb-qr-brand{color:#fff;font-size:11px;white-space:nowrap;}
  .eb-qr-status{display:inline-flex;align-items:center;gap:5px;font-size:10.5px;font-weight:700;background:rgba(255,255,255,.18);padding:4px 10px;border-radius:999px;flex:none;}
  .eb-qr-status i{width:6px;height:6px;border-radius:50%;background:#6BE0A6;display:inline-block;box-shadow:0 0 0 3px rgba(107,224,166,.28);}
  .eb-qr-body{width:100%;box-sizing:border-box;padding:18px 18px 20px;display:flex;flex-direction:column;align-items:center;}
