    border:1px solid var(--ag-gray-200) !important;box-shadow:0 6px 18px rgba(16,24,32,.08);}
  .eb-qr-box img,.eb-qr-box canvas{max-width:100% !important;height:auto !important;display:block;}
  .eb-qr-scanhint{font-size:11px;color:var(--ag-gray-500);margin-top:10px;font-weight:600;letter-spacing:.02em;}
  .eb-qr-name{font-size:17px !important;margin-top:12px !important;}
  .eb-qr-idcard{margin-top:8px !important;}
  .eb-qr-howto{width:100%;max-width:360px;box-sizing:border-box;background:var(--ag-surface);border:1px solid var(--ag-gray-100);border-radius:18px;padding:14px;}
  .eb-qr-howto-title{font-size:12.5px;font-weight:800;color:var(--ag-gray-900);margin-bottom:10px;}
  .eb-qr-step{display:flex;align-items:flex-start;gap:10px;font-size:12.5px;color:var(--ag-gray-600);line-height:1.4;padding:5px 0;}
  .eb-qr-step b{flex:none;width:22px;height:22px;border-radius:50%;background:var(--ag-green-soft);color:var(--ag-green);
    display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:800;}
  .eb-qr-tip{display:flex;gap:8px;align-items:flex-start;margin-top:8px;padding:9px 11px;border-radius:12px;background:var(--ag-green-soft);
    color:var(--ag-green);font-size:11.5px;font-weight:600;line-height:1.4;}
  .eb-qr-tip svg{width:15px;height:15px;flex:none;margin-top:1px;}
