  html[data-theme="dark"] .eb-qr-howto-title{color:#F1F6F3;}

  /* 4) Riwayat Transaksi */
  .eb-trx-stats{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:14px;}
  .eb-trx-stat{border-radius:14px;padding:10px 12px;color:#fff;min-width:0;}
  .eb-trx-stat.s1{background:linear-gradient(135deg,#1E7A4C,#0B3D2E);}
  .eb-trx-stat.s2{background:linear-gradient(135deg,#3B8CF0,#1E5FC2);}
  .eb-trx-stat span{display:block;font-size:9.5px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;opacity:.85;}
  .eb-trx-stat strong{display:block;font-size:16px;font-weight:800;margin-top:3px;overflow-wrap:anywhere;line-height:1.15;}
  .eb-trx-head{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:12px;}
  .eb-trx-head .section-title{margin:0 !important;display:flex;align-items:center;gap:8px;}
