  .eb-trx-date svg{width:11px;height:11px;flex:none;}
  .eb-trx-item-right{flex-direction:column;align-items:flex-end !important;gap:2px !important;}
  .eb-trx-item .eb-trx-amount{font-size:14px !important;}
  .eb-trx-item .eb-trx-chevron{transform:rotate(-90deg);}

  /* 5) Popup Detail Transaksi */
  .eb-trx-hero{position:relative;overflow:hidden;border-radius:18px;padding:18px 14px 16px;text-align:center;color:#fff;
    background:linear-gradient(135deg,#1E7A4C 0%,#0B3D2E 100%);margin-bottom:14px;}
  .eb-trx-hero::before{content:'';position:absolute;width:130px;height:130px;border-radius:50%;background:rgba(255,255,255,.08);top:-50px;right:-36px;}
  .eb-trx-hero-ic{position:relative;width:36px;height:36px;border-radius:50%;background:rgba(255,255,255,.2);margin:0 auto 8px;display:flex;align-items:center;justify-content:center;}
  .eb-trx-hero-ic svg{width:18px;height:18px;}
  .eb-trx-hero-label{position:relative;font-size:10.5px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;opacity:.85;}
  .eb-trx-hero-amount{position:relative;font-size:clamp(22px,7vw,28px);font-weight:800;letter-spacing:-.02em;margin-top:2px;overflow-wrap:anywhere;}
  .eb-trx-hero-no{position:relative;display:inline-block;margin-top:8px;font-size:11.5px;font-weight:700;background:rgba(255,255,255,.18);padding:3px 11px;border-radius:999px;word-break:break-all;}
  .eb-info-list{border:1px solid var(--ag-gray-100);border-radius:16px;background:var(--ag-surface);padding:2px 12px;margin-bottom:14px;}
  .eb-info-row{display:flex;align-items:center;gap:10px;padding:11px 0;border-bottom:1px solid var(--ag-gray-100);}
  .eb-info-row:last-child{border-bottom:none;}
  .eb-info-ic{width:30px;height:30px;border-radius:9px;background:var(--ag-green-soft);color:var(--ag-green);display:flex;align-items:center;justify-content:center;flex:none;}
  .eb-info-ic svg{width:15px;height:15px;}
  .eb-info-txt{min-width:0;flex:1;}
  .eb-info-txt small{display:block;font-size:10.5px;color:var(--ag-gray-400);font-weight:600;text-transform:uppercase;letter-spacing:.04em;}
  .eb-info-txt strong{display:block;font-size:13.5px;color:var(--ag-gray-900);font-weight:700;margin-top:1px;overflow-wrap:anywhere;line-height:1.3;}
  .eb-receipt-title{display:flex;align-items:center;gap:7px;font-size:12px;font-weight:800;color:var(--ag-gray-700);margin-bottom:8px;text-transform:uppercase;letter-spacing:.04em;}
  .eb-receipt-title svg{width:14px;height:14px;color:var(--ag-green);}

  /* ===== PROFILE EMPLOYEE BENEFIT (ebp-*) ===== */
  .ebp{display:flex;flex-direction:column;gap:14px;padding-bottom:90px;}
  .ebp-hero{position:relative;overflow:hidden;border-radius:22px;padding:22px 16px 18px;text-align:center;color:#fff;
    background:linear-gradient(135deg,#1E7A4C 0%,#0B3D2E 100%);box-shadow:0 10px 24px rgba(11,61,46,.22);}
  .ebp-hero::before{content:'';position:absolute;width:170px;height:170px;border-radius:50%;background:rgba(255,255,255,.08);top:-70px;right:-50px;}
  .ebp-hero::after{content:'';position:absolute;width:110px;height:110px;border-radius:50%;background:rgba(255,255,255,.05);bottom:-50px;left:-30px;}
  .ebp-hero > *{position:relative;z-index:1;}
  .ebp-avatar{width:68px;height:68px;border-radius:50%;margin:0 auto 10px;display:flex;align-items:center;justify-content:center;
    font-size:24px;font-weight:800;background:rgba(255,255,255,.2);border:3px solid rgba(255,255,255,.55);}
  .ebp-name{font-size:19px;font-weight:800;letter-spacing:-.01em;line-height:1.25;overflow-wrap:anywhere;}
