  .ebp-row:last-child{border-bottom:none;}
  .ebp-ic{width:34px;height:34px;border-radius:11px;background:var(--ag-green-soft);color:var(--ag-green);display:flex;align-items:center;justify-content:center;flex:none;}
  .ebp-ic svg{width:16px;height:16px;}
  .ebp-txt{min-width:0;flex:1;}
  .ebp-txt small{display:block;font-size:10.5px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--ag-gray-400);}
  .ebp-txt strong{display:block;font-size:14px;font-weight:700;color:var(--ag-gray-900);margin-top:2px;line-height:1.35;overflow-wrap:anywhere;word-break:normal;}
