  .ebp-pw-txt small{display:block;font-size:11.5px;color:var(--ag-gray-500);margin-top:2px;}
  .ebp-chev{transform:rotate(-90deg);color:var(--ag-gray-400);display:flex;}
  .ebp-chev svg{width:16px;height:16px;}
  .ebp-pw-btn:active .ebp-ic{background:var(--ag-green);color:#fff;}
