  /* ===== Menu Lainnya v2: cerah, modern, ikon warna-warni (tema terang) ===== */
  html:not([data-theme="dark"]) .bottom-more-sheet{background:linear-gradient(180deg,#FFFFFF 0%,#F3F8F5 100%) !important;}
  .bottom-more-sheet{border-radius:26px 26px 0 0 !important;box-shadow:0 -12px 40px rgba(16,24,32,.18) !important;}
