  #bottomMoreSheetNav{gap:10px !important;padding:6px 16px 28px !important;}
  #bottomMoreSheetNav .bottom-sheet-group-label{margin:12px 2px 0 !important;color:var(--ag-gray-500) !important;font-size:10.5px !important;}
  #bottomMoreSheetNav .bottom-sheet-group-label::after{background:linear-gradient(90deg,var(--ag-gray-200),transparent) !important;}
  #bottomMoreSheetNav .nav-item{--tint:#E7F3EC;--ink:#1E7A4C;
    padding:11px 12px !important;border-radius:18px !important;border:1px solid rgba(16,24,32,.06) !important;
    background:#fff !important;box-shadow:0 4px 14px rgba(16,24,32,.06) !important;}
  #bottomMoreSheetNav .nav-item:nth-child(6n+2){--tint:#E8F0FE;--ink:#2F80ED;}
  #bottomMoreSheetNav .nav-item:nth-child(6n+3){--tint:#FDEEDC;--ink:#E0801F;}
  #bottomMoreSheetNav .nav-item:nth-child(6n+4){--tint:#F0E9FD;--ink:#7C4DDB;}
  #bottomMoreSheetNav .nav-item:nth-child(6n+5){--tint:#DDF5F1;--ink:#0F9C8E;}
  #bottomMoreSheetNav .nav-item:nth-child(6n+6){--tint:#FCE7F1;--ink:#D6336C;}
  #bottomMoreSheetNav .nav-item .nav-icon{width:38px !important;height:38px !important;flex:0 0 38px !important;border-radius:13px !important;
    background:var(--tint) !important;color:var(--ink) !important;}
  #bottomMoreSheetNav .nav-item .nav-icon svg{width:19px !important;height:19px !important;stroke:var(--ink) !important;}
  #bottomMoreSheetNav .nav-item .nav-label{color:var(--ag-gray-900,#1f2d27) !important;font-size:13px !important;font-weight:700 !important;}
  /* aktif: terang, bukan hijau gelap */
  #bottomMoreSheetNav .nav-item.active{background:linear-gradient(135deg,#EAF7F0 0%,#FFFFFF 100%) !important;
    border:1.5px solid #34A56F !important;box-shadow:0 8px 20px rgba(30,122,76,.16) !important;}
  #bottomMoreSheetNav .nav-item.active .nav-icon{background:linear-gradient(135deg,#34B27B,#1E7A4C) !important;color:#fff !important;box-shadow:0 4px 10px rgba(30,122,76,.3);}
  #bottomMoreSheetNav .nav-item.active .nav-icon svg{stroke:#fff !important;}
  #bottomMoreSheetNav .nav-item.active .nav-label{color:#1E7A4C !important;font-weight:800 !important;}
  #bottomMoreSheetNav .nav-item.active::after{content:'';position:absolute;right:10px;bottom:10px;width:7px;height:7px;border-radius:50%;background:#34A56F;box-shadow:0 0 0 3px rgba(52,165,111,.2);}
  #bottomMoreSheetNav .nav-item .nav-badge{top:-6px !important;right:-4px !important;background:linear-gradient(135deg,#F2994A,#E0701A) !important;color:#fff !important;border:2px solid #fff;box-shadow:0 2px 6px rgba(224,112,26,.4);}
  html[data-theme="dark"] #bottomMoreSheetNav .nav-item{background:#18221D !important;border-color:rgba(255,255,255,.08) !important;}
  html[data-theme="dark"] #bottomMoreSheetNav .nav-item .nav-label{color:#F1F6F3 !important;}
  html[data-theme="dark"] #bottomMoreSheetNav .nav-item.active{background:linear-gradient(135deg,#1F3A2D,#18221D) !important;}
  html[data-theme="dark"] #bottomMoreSheetNav .nav-item.active .nav-label{color:#6BE0A6 !important;}

  /* ===== Sidebar collapsed: label seksi tidak boleh terpotong ===== */
  .sidebar.collapsed .nav-section-label{font-size:0 !important;line-height:0;height:1px;padding:0 !important;margin:10px 18px !important;background:rgba(255,255,255,.2);overflow:hidden;border-radius:1px;}
  .sidebar.collapsed .nav-divider{margin:8px 18px !important;}
  .sidebar.collapsed .sidebar-nav{padding-top:8px !important;}

  /* ===== Hilangkan header judul menu (sudah ada di topbar) ===== */
  .table-toolbar > .card-title,.list-header > .card-title{display:none !important;}
  .table-toolbar,.list-header{justify-content:flex-end;}
  .table-toolbar:not(:has(> :not(.card-title))),.list-header:not(:has(> :not(.card-title))){display:none !important;}
  .card-header:has(> .card-title:only-child):has(+ .filter-bar){display:none !important;}
  .card-header:has(> .card-title:only-child):has(+ .filter-bar--c){display:none !important;}

  /* ===== Kelola Employee: kartu ringkas ===== */
  .eb-emp-page .data-card{padding:10px 12px !important;gap:8px !important;}
  .eb-emp-page .data-card-grid{gap:6px !important;padding:8px !important;}
  .eb-emp-page .data-card-field{padding:7px 10px !important;gap:2px !important;border-radius:11px !important;}
  .eb-emp-page .data-card-field span{font-size:9px !important;}
  .eb-emp-page .data-card-field b{font-size:12.5px !important;}
  .eb-emp-page .data-card-field .id-chip{font-size:11px;padding:2px 8px;}
  .eb-emp-page .data-card-field .badge{font-size:10.5px !important;padding:3px 8px !important;}
  .eb-emp-page .data-card-field b div{font-size:12.5px;line-height:1.3;}
  .eb-emp-page .data-card-field b div + div{font-size:10.5px;font-weight:500;color:var(--ag-gray-500);}
  .eb-emp-page .dc-main,.eb-emp-page .data-card-top{margin-bottom:0 !important;}

  /* ===== Nama di kartu tidak boleh terpotong ===== */
  .data-card .dc-main{flex-wrap:wrap !important;align-items:center;row-gap:8px;}
  .data-card .dc-main-text,.data-card .dc-main-text *{white-space:normal !important;overflow:visible !important;text-overflow:clip !important;}
  .data-card .dc-main-text{flex:1 1 140px;min-width:0;overflow-wrap:anywhere;}
  .data-card .dc-main-text .cell-agent-name{white-space:normal !important;line-height:1.25;}
  .data-card .dc-main:has(.dc-actions .row-actions > :nth-child(3)) .dc-main-text{flex:1 1 100%;}
  .data-card .dc-main:has(.dc-actions .row-actions > :nth-child(3)) .dc-actions{flex:1 1 100%;justify-content:flex-end;}
  .data-card .dc-actions{flex:0 0 auto;}

  /* ===== Tombol aksi rata kanan; badge status selalu 1 baris ===== */
  .data-card .dc-actions{display:flex;justify-content:flex-end;margin-left:auto;}
  .data-card .dc-actions .row-actions{justify-content:flex-end !important;flex-wrap:nowrap !important;width:auto;}
  .data-card .dc-main:has(.dc-actions > .row-actions > :nth-child(3)) .dc-actions{flex:1 1 100%;}
  .data-card-field .badge,.data-card-field:has(.badge) b .badge{white-space:nowrap !important;max-width:100%;font-size:10.5px !important;padding:3px 8px !important;gap:5px;}
  .data-card-field:has(.badge) b{white-space:nowrap !important;overflow:visible !important;}

  /* ===== Badge status: pill ikut selebar teks (tidak ada teks keluar dari latar) ===== */
  .data-card-field .badge,.data-card-field b .badge{display:inline-flex !important;align-items:center;width:fit-content !important;max-width:none !important;flex:none;line-height:1.2;}
  .data-card-field:has(.badge){overflow:visible;}

  /* ===== Order (desktop): tabel rapi, status 1 baris, tanpa scroll horizontal ===== */
  @media (min-width:761px){
    .orders-page .data-table{table-layout:auto !important;width:100%;}
    .orders-page .data-table thead th,.orders-page .data-table tbody td{overflow:visible !important;text-overflow:clip !important;white-space:nowrap !important;padding-left:7px !important;padding-right:7px !important;}
    .orders-page .data-table td .mono-id{display:inline-block;overflow:visible;text-overflow:clip;max-width:none;font-size:11.5px;}
    .orders-page .data-table td .badge{display:inline-flex !important;align-items:center;width:fit-content !important;max-width:none !important;white-space:nowrap !important;font-size:11px !important;padding:3px 9px !important;}
    .orders-page .data-table td .cell-agent{max-width:220px;min-width:0;}
    .orders-page .data-table td .cell-agent-name,.orders-page .data-table td .cell-agent-sub{display:block;overflow:hidden !important;text-overflow:ellipsis !important;white-space:nowrap !important;max-width:220px;}
    .orders-page .table-scroll{overflow-x:hidden !important;}
    .orders-page .data-table td:last-child .row-actions{flex-wrap:nowrap;justify-content:flex-start;}
  }
  @media (min-width:761px) and (max-width:1700px){
    .orders-page .data-table th:nth-child(9),.orders-page .data-table td:nth-child(9){display:none;}
  }
  @media (min-width:761px) and (max-width:1500px){
    .orders-page .data-table th:nth-child(3),.orders-page .data-table td:nth-child(3){display:none;}
    .orders-page .data-table td .cell-agent,.orders-page .data-table td .cell-agent-name,.orders-page .data-table td .cell-agent-sub{max-width:170px;}
  }
  @media (min-width:761px) and (max-width:1350px){
    .orders-page .data-table th:nth-child(7),.orders-page .data-table td:nth-child(7){display:none;}
    .orders-page .data-table td .cell-agent-sub{display:none;}
  }

  /* ===== Order desktop v2: semua kolom penting + tombol Aksi selalu terlihat ===== */
  @media (min-width:761px){
    .orders-page .data-table th:nth-child(9),.orders-page .data-table td:nth-child(9){display:none !important;}
    .orders-page .data-table thead th,.orders-page .data-table tbody td{padding-left:6px !important;padding-right:6px !important;}
    .orders-page .data-table td:nth-child(3){max-width:120px;overflow:hidden !important;text-overflow:ellipsis !important;}
    .orders-page .data-table td:nth-child(4) .cell-agent,.orders-page .data-table td:nth-child(4) .cell-agent-name,.orders-page .data-table td:nth-child(4) .cell-agent-sub{max-width:170px;}
    .orders-page .data-table td:nth-child(5) .cell-agent,.orders-page .data-table td:nth-child(5) .cell-agent-name,.orders-page .data-table td:nth-child(5) .cell-agent-sub{max-width:150px;}
    .orders-page .data-table td .mono-id{font-size:11px;}
    .orders-page .data-table td .badge{font-size:10.5px !important;padding:3px 8px !important;}
    .orders-page .data-table td:last-child,.orders-page .data-table th:last-child{width:1%;white-space:nowrap;}
    .orders-page .data-table td:last-child .action-btn{width:30px;height:30px;}
  }
  @media (min-width:761px) and (max-width:2100px){
    .orders-page .data-table th:nth-child(3),.orders-page .data-table td:nth-child(3){display:none !important;}
  }
  @media (min-width:761px) and (max-width:1850px){
    .orders-page .data-table th:nth-child(7),.orders-page .data-table td:nth-child(7){display:none !important;}
  }
  @media (min-width:761px) and (max-width:1600px){
    .orders-page .data-table td .cell-agent-sub{display:none !important;}
    .orders-page .data-table td:nth-child(4) .cell-agent-name{max-width:130px;}
    .orders-page .data-table td:nth-child(5) .cell-agent-name{max-width:120px;}
  }
  @media (min-width:761px) and (max-width:1400px){
    .orders-page .data-table th:nth-child(8),.orders-page .data-table td:nth-child(8){display:none !important;}
  }

  /* ===== Pill tipe agent (PO / Order) ===== */
  .agent-type-pill{white-space:nowrap !important;display:inline-flex !important;align-items:center;width:fit-content;font-size:10.5px !important;padding:3px 9px !important;font-weight:700;}
  .agent-type-pill::before{content:'';width:6px;height:6px;border-radius:50%;background:currentColor;margin-right:6px;flex:none;}
  .po-card-agent-type{margin-top:6px;}

  /* ===== Kartu Order (mobile): Pengiriman & Penyelesaian sebaris ===== */
  @media (max-width:760px){
    .orders-page .data-card-grid{grid-template-columns:repeat(20,minmax(0,1fr)) !important;}
    .orders-page .data-card-field{grid-column:span 10;}
    .orders-page .data-card-field.full-w{grid-column:1 / -1;}
    .orders-page .data-card-field.dc-st-a{grid-column:span 9;}
    .orders-page .data-card-field.dc-st-b{grid-column:span 11;}
    .orders-page .data-card-field.dc-st-a,.orders-page .data-card-field.dc-st-b{padding-left:9px !important;padding-right:6px !important;}
    .orders-page .dc-st-a .badge,.orders-page .dc-st-b .badge{font-size:10px !important;padding:3px 7px !important;gap:4px;}
  }

  /* ===== Kartu Order mobile (oc-*): ringkas, tidak ada teks yang melebihi kartu ===== */
  .oc{background:var(--ag-surface);border:1px solid var(--ag-gray-200);border-radius:18px;padding:12px 13px;display:flex;flex-direction:column;gap:9px;
    box-shadow:0 4px 14px rgba(16,24,32,.06);min-width:0;box-sizing:border-box;overflow:hidden;}
  .oc-head{display:flex;align-items:center;justify-content:space-between;gap:8px;min-width:0;}
  .oc-id{font-size:11.5px;font-weight:700;background:var(--ag-green-soft);color:var(--ag-green);padding:4px 10px;border-radius:999px;white-space:nowrap;}
  .oc-date{display:inline-flex;align-items:center;gap:5px;font-size:11.5px;color:var(--ag-gray-500);font-weight:600;white-space:nowrap;}
  .oc-date svg{width:13px;height:13px;flex:none;}
  .oc-agent{display:flex;align-items:center;flex-wrap:wrap;gap:4px 8px;min-width:0;}
  .oc-agent-name{font-size:15px;font-weight:800;color:var(--ag-gray-900);line-height:1.25;overflow-wrap:anywhere;min-width:0;}
  .oc-sub{font-size:11.5px;color:var(--ag-gray-500);margin-top:-5px;overflow-wrap:anywhere;}
  .oc-agent + .oc-sub{margin-top:-4px;}
  .oc-store{display:flex;gap:9px;align-items:flex-start;background:var(--ag-gray-50);border-radius:12px;padding:8px 10px;min-width:0;}
  .oc-store-ic{flex:0 0 26px;height:26px;border-radius:8px;background:var(--ag-green-soft);color:var(--ag-green);display:flex;align-items:center;justify-content:center;}
  .oc-store-ic svg{width:14px;height:14px;}
  .oc-store-txt{min-width:0;display:flex;flex-direction:column;gap:1px;}
  .oc-store-txt b{font-size:13px;font-weight:700;color:var(--ag-gray-900);overflow-wrap:anywhere;}
  .oc-store-txt small{font-size:11px;color:var(--ag-gray-500);line-height:1.35;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;}
  .oc-stats{display:grid;grid-template-columns:1.15fr 1fr 1fr;gap:6px;}
  .oc-stats > div{background:var(--ag-gray-50);border-radius:11px;padding:7px 9px;min-width:0;}
  .oc-stats span{display:block;font-size:9px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--ag-gray-500);}
  .oc-stats b{display:block;font-size:12px;font-weight:700;color:var(--ag-gray-900);margin-top:2px;overflow-wrap:anywhere;line-height:1.25;}
  .oc-stats b.oc-muted{color:var(--ag-gray-500);font-weight:600;}
  .oc-foot{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;border-top:1px dashed var(--ag-gray-200);padding-top:9px;}
  .oc-badges{display:flex;flex-wrap:wrap;gap:5px;min-width:0;}
  .oc-badges .badge{white-space:nowrap !important;font-size:10px !important;padding:3px 8px !important;display:inline-flex !important;width:fit-content !important;max-width:none !important;}
  .oc-actions{margin-left:auto;display:flex;}
  .oc-actions .row-actions{flex-wrap:nowrap !important;justify-content:flex-end !important;gap:5px !important;}
  .oc-actions .action-btn{width:30px;height:30px;}

  /* ===== Kartu Order v2: Total & Pengambilan 2 kolom (1 baris), Promo 1 baris dipotong rapi ===== */
  .oc-stats{grid-template-columns:1fr 1fr !important;}
  .oc-stats b{white-space:nowrap !important;overflow:hidden;text-overflow:ellipsis;overflow-wrap:normal !important;}
  .oc-promo{display:flex;align-items:center;gap:7px;min-width:0;background:var(--ag-green-soft);color:var(--ag-green);border-radius:11px;padding:6px 10px;font-size:11.5px;font-weight:700;}
  .oc-promo-ic{flex:0 0 auto;display:flex;}
  .oc-promo-ic svg{width:13px;height:13px;}
  .oc-promo-txt{min-width:0;flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}

  /* ===== Kartu mobile PO / Commission / Skema Komisi (gaya Order) ===== */
  .oc-head .badge{white-space:nowrap !important;display:inline-flex !important;width:fit-content !important;max-width:none !important;font-size:10px !important;padding:3px 9px !important;flex:none;}
  .oc-id-text{font-family:inherit !important;font-size:12.5px !important;white-space:normal !important;overflow-wrap:anywhere;min-width:0;}
  .oc-head{align-items:center;}
  .oc-stats.c3{grid-template-columns:1.35fr 1fr 1fr !important;}
  .oc-stats.c3 > div{padding:7px 8px;}
  .oc-stats .oc-hl{background:var(--ag-green-soft);}
  .oc-stats .oc-hl b,.oc-stats .oc-hl span{color:var(--ag-green);}
  .oc-amount{display:flex;align-items:center;justify-content:space-between;gap:8px;background:var(--ag-green-soft);border-radius:12px;padding:8px 11px;}
  .oc-amount > div > span{display:block;font-size:9px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--ag-green);}
  .oc-amount b{display:block;font-size:16px;font-weight:800;color:var(--ag-green);white-space:nowrap;margin-top:1px;}
  .oc-foot:has(.oc-badges:empty):not(:has(.oc-actions > *)){display:none;}
  .oc-badges:empty{display:none;}
  .oc-foot:has(.oc-badges:empty){justify-content:flex-end;}

  /* ===== Fix kolom tanggal kartu PO/Commission ===== */
  .oc-stats.c3{grid-template-columns:minmax(max-content,1.25fr) minmax(max-content,1.1fr) minmax(0,.75fr) !important;}
  .oc-stats.c3 > div:nth-child(3) b{font-size:11px;}
  .oc-stats.c3 > div{padding:7px 8px;}

  /* ===== Kartu mobile Data Agent / Master Item / Store / Area / Departemen ===== */
  .oc-person{display:flex;gap:10px;align-items:flex-start;min-width:0;}
  .oc-person-txt{min-width:0;flex:1;display:flex;flex-direction:column;gap:3px;}
  .oc-person-txt .oc-sub{margin-top:0 !important;}
  .oc-avatar{flex:0 0 40px;width:40px;height:40px;border-radius:50%;background:var(--ag-green);color:#fff;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:14px;}
  .oc-thumb{flex:0 0 52px;width:52px;height:52px;border-radius:12px;object-fit:cover;border:1px solid var(--ag-gray-200);}
  .oc-thumb-ph{display:flex;align-items:center;justify-content:center;background:var(--ag-gray-100);color:var(--ag-gray-400);}
  .oc-thumb-ph svg{width:22px;height:22px;}
  .oc-kv{display:inline-flex;align-items:center;gap:5px;}
  .oc-kv i{font-style:normal;font-size:9px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--ag-gray-500);}
  .oc-stats.wrap b{white-space:normal !important;overflow-wrap:anywhere !important;}
  .oc-muted{color:var(--ag-gray-400);}
  .oc-head .mono-id.oc-id{max-width:70%;overflow:hidden;text-overflow:ellipsis;}
  .oc-amount .price-stack{display:flex;align-items:baseline;gap:6px;flex-wrap:wrap;}
  .oc-amount .agent-product-price{font-size:16px;font-weight:800;color:var(--ag-green);}
  .oc-amount .price-strike{font-size:11px;}
  .oc-foot .oc-actions{flex-wrap:wrap;justify-content:flex-end;max-width:100%;}
  .oc-foot .oc-actions .ag-act-top{display:flex;gap:6px;margin-bottom:6px;justify-content:flex-end;}

  /* ===== Kartu mobile: Kelola User & Audit Log (gaya Order) ===== */
  .oc-detail{font-size:12px;line-height:1.45;color:var(--ag-gray-700);background:var(--ag-gray-50);border-radius:11px;padding:8px 10px;overflow-wrap:anywhere;
    display:-webkit-box;-webkit-line-clamp:5;-webkit-box-orient:vertical;overflow:hidden;}
  .oc-head .badge{max-width:60%;}
  .oc.is-off{opacity:.78;}
  .oc-user .oc-avatar{background:linear-gradient(135deg,#17b37c,#0c8f63);box-shadow:0 4px 10px -4px rgba(12,143,99,.55);}
  .oc-avatar-sm{flex-basis:34px;width:34px;height:34px;font-size:12px;background:var(--ag-green-soft);color:var(--ag-green);}
  .oc-mail{display:flex;align-items:center;gap:5px;}
  .oc-mail svg{width:12px;height:12px;flex:none;}
  .oc-mail span{min-width:0;overflow-wrap:anywhere;}
  .oc-time{display:inline-flex;align-items:center;gap:5px;font-size:11px;font-weight:600;color:var(--ag-gray-500);}
  .oc-time svg{width:13px;height:13px;}
  .oc-audit .oc-foot{padding-top:7px;}

  /* Ringkasan angka di atas daftar (Kelola User / Audit Log) */
  .pg-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin:2px 0 10px;}
  .pg-stats.pg-3{grid-template-columns:repeat(3,minmax(0,1fr));}
  .pg-stats > div{background:var(--ag-gray-50);border:1px solid var(--ag-gray-200);border-radius:14px;padding:9px 11px;min-width:0;}
  .pg-stats span{display:block;font-size:9px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--ag-gray-500);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
  .pg-stats b{display:block;font-size:18px;font-weight:800;color:var(--ag-gray-900);margin-top:2px;line-height:1.1;}
  .pg-stats .pg-hl{background:var(--ag-green-soft);border-color:transparent;}
  .pg-stats .pg-hl b,.pg-stats .pg-hl span{color:var(--ag-green);}
