  #loginScreen .login-heading{ font-size:27px; line-height:1.2; margin:0 0 8px; color:var(--lg-ink); white-space:normal; overflow-wrap:anywhere; text-align:left; }
  #loginScreen .login-subheading{ font-size:14px; line-height:1.55; margin:0; color:var(--lg-mute); text-align:left; }

  #loginScreen .form-group{ margin-bottom:16px; }
