  #loginScreen .input-with-icon input:focus{ outline:none; background:#fff; border-color:var(--lg-green); box-shadow:0 0 0 4px rgba(30,122,76,.14); }
  #loginScreen .input-with-icon .field-icon{ left:15px; width:18px; height:18px; color:#8FA699; transition:color .15s; }
