  /* =========================================================
     BADGE STATUS DI KARTU HERO HIJAU (Cek Status / Profil):
     pil transparan putih yang menyatu dengan latar hijau; warna status hanya di titiknya.
     Menimpa aturan .badge-blue/.badge-* (!important) yang membuatnya tampak biru berpendar.
     ========================================================= */
  html .profile-hero .profile-hero-badges .badge{background:rgba(255,255,255,.16) !important;color:#fff !important;
    border:1px solid rgba(255,255,255,.38) !important;box-shadow:none !important;text-shadow:none;}
  html .profile-hero .profile-hero-badges .badge::before{background:#bfdbfe;}
  html .profile-hero .profile-hero-badges .badge-green::before{background:#86efac;}
  html .profile-hero .profile-hero-badges .badge-red::before{background:#fca5a5;}
  html .profile-hero .profile-hero-badges .badge-orange::before{background:#fcd34d;}
  html .profile-hero .profile-hero-badges .badge-neutral::before{background:#e5e7eb;}
  html .profile-hero .profile-hero-badges .badge-purple::before{background:#d8b4fe;}

  /* ===== FIX: tombol Tambah (Produk/User/dst) tidak mepet ke atas ===== */
  .table-toolbar,.list-header{padding-top:14px;}
  @media (max-width:760px){
    .table-toolbar,.list-header{padding-top:10px;}
    .content > .card:has(> .filter-bar) > .list-header,
    .content > .card:has(> .data-card-list) > .list-header{ padding-top:10px !important; }
  }

  /* ===== FIX DESKTOP: hilangkan "kolom di dalam kolom" — pembungkus .card luar dibuat transparan
     (sama seperti mode HP) sehingga filter + tabel hanya 1 lapis. Mode HP tidak diubah. ===== */
  @media (min-width:761px){
    .content > .card:has(> .filter-bar){
      background:transparent !important; border:0 !important; box-shadow:none !important;
      border-radius:0 !important; padding:0 !important;
    }
    .content > .card:has(> .filter-bar) > .filter-bar{ margin:0 0 12px !important; }
    .content > .card:has(> .filter-bar) > .list-header,
    .content > .card:has(> .filter-bar) > .table-toolbar{ margin-bottom:10px !important; padding-top:2px !important; }
    .content > .card:has(> .filter-bar) > .empty-state{
      background:var(--ag-surface);border:1px solid var(--ag-gray-200);border-radius:18px;padding:40px 16px;
    }
  }
  .users-page > .kpi-grid{ margin-left:0 !important; margin-right:0 !important; }

  /* ===== Pagination universal (ringkas, 1 baris) ===== */
  .pgn-bar{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-top:12px;padding:8px 12px;background:var(--ag-surface,#fff);border:1px solid var(--ag-gray-200,#e5ece8);border-radius:14px;font-size:12.5px;color:var(--ag-gray-600,#4b5b53);}
  .pgn-info b{color:var(--ag-gray-900,#0f1f18);font-weight:700;}
  .pgn-ctrl{display:flex;align-items:center;gap:8px;}
  .pgn-size{height:30px;padding:0 24px 0 10px;border:1px solid var(--ag-gray-200,#e5ece8);border-radius:9px;background:var(--ag-surface,#fff);color:inherit;font:inherit;font-size:12px;cursor:pointer;}
  .pgn-btn{height:30px;padding:0 12px;border:1px solid var(--ag-gray-200,#e5ece8);border-radius:9px;background:var(--ag-surface,#fff);color:var(--ag-green-700,#0c8f63);font:inherit;font-size:12px;font-weight:700;cursor:pointer;display:inline-flex;align-items:center;gap:4px;transition:background .15s,border-color .15s;}
  .pgn-btn:hover:not(:disabled){background:rgba(23,179,124,.1);border-color:rgba(23,179,124,.45);}
  .pgn-btn:disabled{opacity:.4;cursor:not-allowed;}
  .pgn-pg{min-width:44px;text-align:center;font-weight:700;color:var(--ag-gray-900,#0f1f18);font-variant-numeric:tabular-nums;}
  @media (max-width:760px){
    .pgn-bar{padding:7px 8px;gap:6px;border-radius:12px;font-size:11.5px;}
    .pgn-ctrl{gap:5px;width:100%;justify-content:space-between;}
    .pgn-btn{padding:0 10px;}
    .pgn-pg{min-width:38px;}
  }

  .kpi-grid.kpi-grid-page{margin:0 0 14px !important;}
